+        Ok(match operator.kind() {
+            T![+] => JsUnaryOperator::Plus,
+            T![-] => JsUnaryOperator::Minus,
+            T![~] => JsUnaryOperator::BitwiseNot,
+            T![!] => JsUnaryOperator::LogicalNot,
+            T![typeof] => JsUnaryOperator::Typeof,
